private static final Map<String, String> CITY_REGION = Map.of(
    "Sydney", "NSW",
    "Melbourne", "VIC",
    "Brisbane", "QLD");

/**
 * The owner's locality: the canonical region derived from {@link #getCity() city} via the fixed
 * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or
 * {@code "UNKNOWN"} when the city is not in the table.
 */
public String getLocality() {
    return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
}

/**
 * The owner's preferred contact channel: {@code "EMAIL"} when an email is present, otherwise
 * {@code "PHONE"}.
 */
public String getContactPreference() {
    boolean hasEmail = this.email != null && !this.email.isBlank();
    return hasEmail ? "EMAIL" : "PHONE";
}

/**
 * The owner's derived identity key — the single value all duplicate detection is expressed through:
 * {@code telephone + "|" + (email or empty) + "|" + householdId}, using the owner's stored canonical
 * telephone (E.164), its lower-cased email (empty when absent) and its household id. Two owners are
 * duplicates exactly when their whole identity keys are equal.
 */
public String getIdentityKey() {
    String tel = this.telephone == null ? "" : this.telephone;
    String mail = (this.email == null || this.email.isBlank()) ? "" : this.email;
    String household = this.householdId == null ? "" : this.householdId;
    return tel + "|" + mail + "|" + household;
}

protected Set<Pet> getPetsInternal() {
    if (this.pets == null) {
        this.pets = new HashSet<>();
    }

